var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if(scene.name!="BlackHoleStationEcologicalParkV017"||UnityEditor.EditorApplication.isPlaying)throw new System.Exception("V017 Edit required");
var objects=UnityEngine.Object.FindObjectsByType<UnityEngine.MeshRenderer>(UnityEngine.FindObjectsSortMode.None).Where(r=>r.gameObject.scene==scene&&(r.name.Contains("conservatory entry bowed entry canopy")||r.name=="Ecology entrance sage fascia")).Select(r=>r.gameObject).ToArray();
if(objects.Length!=5)throw new System.Exception("Expected four park entry canopies and shared fascia");
var rows=objects.Select(go=>new{go.name,path=UnityEditor.AnimationUtility.CalculateTransformPath(go.transform,null)}).ToArray();
foreach(var go in objects){UnityEditor.Undo.RecordObject(go,"Remove all remaining park entry overhangs");go.SetActive(false);}
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
